script:
// Maple Grove v19 - life-size suburb: tap-to-open doors, a real pool and pond.
// Admin commands live in Menu -> Admin -> World (they also work in chat: /tp pool).
var HOUSES = [[-156,-123],[-96,-123],[-36,-123],[24,-123],[84,-123],[144,-123],[-144,123],[-84,123],[-24,123],[36,123],[96,123],[156,123],[-143,-44],[-143,6],[-143,56],[143,-56],[143,-6],[143,44],[97,-39],[97,51]];
var SPOTS = { spawn: [0, 70], park: [0, 60], pool: [-62, 44], pond: [-22, 46], store: [-99, -46], court: [-23, -12], swings: [24, -48] };
var PLACES = ['spawn', 'park', 'pool', 'pond', 'store', 'court', 'swings'];

Game.on('join', function (name) { Game.toast(name + ' moved into Maple Grove'); });

function forMe(d) { return d && (d.to === 'all' || d.to === Game.myId()); }
function who(id) { return id === 'all' ? 'everyone' : (Game.playerName(id) || 'player'); }
function go(s) { Game.tp(s[0], 14, s[1]); }

// admin -> everyone messages: receivers check the sender really is an admin
Game.onNet('doors', function (d, from) { if (Game.isAdmin(from) && d && Game.setDoors(d.m)) Game.toast('Doors: ' + (d.m === 'auto' ? 'normal' : d.m)); });
Game.onNet('time', function (d, from) { if (Game.isAdmin(from) && d && isFinite(d.h)) Game.setTime(+d.h); });
Game.onNet('hl', function (d, from) { if (Game.isAdmin(from) && forMe(d)) Game.heal(9999); });
Game.onNet('br', function (d, from) { if (Game.isAdmin(from) && forMe(d) && d.to !== 'all') Game.tp(+d.x, +d.y, +d.z); });
function party() { Game.setTime(20); Game.banner('BLOCK PARTY! Every door in Maple Grove is open.'); }
Game.onNet('party', function (d, from) { if (Game.isAdmin(from)) party(); });
function poolParty() { Game.setTime(14); go([-86 + Math.random() * 12, 50 + Math.random() * 11]); Game.banner('POOL PARTY! Everybody in the water!'); }
Game.onNet('pp', function (d, from) { if (Game.isAdmin(from)) poolParty(); });

// ---------- Doors ----------
Game.command({ id: 'doors', cat: 'Doors', label: 'Open / close every door', desc: 'Swings all 21 doors at once for everyone. Players can still tap them after.',
  args: [{ n: 'state', t: 'pick', o: ['open', 'close'], d: 'open' }],
  quick: [['Open all', { state: 'open' }], ['Close all', { state: 'close' }]],
  run: function (a) { var n = Game.setAllDoors(a.state === 'open'); return (a.state === 'open' ? 'Opened ' : 'Closed ') + n + ' doors.'; } });
Game.command({ id: 'doorlock', cat: 'Doors', label: 'Door override', desc: 'Normal = tap to open. Locked = nobody gets in. Open = every door stays open.',
  args: [{ n: 'mode', t: 'pick', o: ['normal', 'locked', 'open'], d: 'normal' }],
  quick: [['Normal', { mode: 'normal' }], ['Lock all', { mode: 'locked' }], ['Hold open', { mode: 'open' }]],
  run: function (a) { var m = a.mode === 'normal' ? 'auto' : a.mode; if (!Game.setDoors(m)) return 'Unknown mode.'; Game.broadcast('doors', { m: m }); return 'Doors: ' + a.mode + ' for everyone.'; } });

// ---------- Teleport ----------
Game.command({ id: 'tp', cat: 'Teleport', label: 'Go to a place', desc: 'Jump to a spot around town.',
  args: [{ n: 'place', t: 'pick', o: PLACES, d: 'pool' }],
  quick: [['Pool', { place: 'pool' }], ['Park', { place: 'park' }], ['Store', { place: 'store' }], ['Court', { place: 'court' }], ['Pond', { place: 'pond' }]],
  run: function (a) { var s = SPOTS[a.place]; if (!s) return 'Unknown place.'; go(s); } });
Game.command({ id: 'house', cat: 'Teleport', label: 'Go to a house', desc: 'Stand on the front walk of house 1-20.',
  args: [{ n: 'number', t: 'num', d: 1, min: 1, max: HOUSES.length }],
  run: function (a) { go(HOUSES[Math.round(a.number) - 1]); } });
Game.command({ id: 'bring', cat: 'Teleport', label: 'Bring player', desc: 'Pull a player to where you are standing.',
  args: [{ n: 'player', t: 'player', d: '' }],
  run: function (a) {
    if (!a.player || a.player === Game.myId()) return 'Pick another player.';
    var me = Game.pos(); Game.broadcast('br', { to: a.player, x: me.x + 3, y: me.y, z: me.z }); return 'Bringing ' + who(a.player) + '.';
  } });

// ---------- Fun ----------
Game.command({ id: 'party', cat: 'Fun', label: 'Block party', desc: 'Evening sky and every door flung open.',
  run: function () { party(); Game.setAllDoors(true); Game.broadcast('party', {}); } });
Game.command({ id: 'poolparty', cat: 'Fun', label: 'Pool party', desc: 'Sunny afternoon and EVERYONE is teleported into the pool.',
  run: function () { poolParty(); Game.broadcast('pp', {}); } });

// ---------- World ----------
Game.command({ id: 'time', cat: 'World', label: 'Time of day', desc: 'Change the sky for everyone.',
  args: [{ n: 'hour', t: 'num', d: 12, min: 0, max: 24 }],
  quick: [['Morning', { hour: 8 }], ['Noon', { hour: 12 }], ['Sunset', { hour: 18.5 }], ['Night', { hour: 0 }]],
  run: function (a) { Game.setTime(a.hour); Game.broadcast('time', { h: a.hour }); return 'Time set to ' + a.hour + ':00 for everyone.'; } });
Game.command({ id: 'heal', cat: 'World', label: 'Heal', desc: 'Full health for a player or everyone.',
  args: [{ n: 'player', t: 'player', d: '', o: ['all'] }], quick: [['Me', { player: 'me' }], ['Everyone', { player: 'all' }]],
  run: function (a) {
    var to = a.player === 'me' || !a.player ? Game.myId() : a.player;
    if (to === Game.myId() || to === 'all') Game.heal(9999);
    if (to !== Game.myId()) Game.broadcast('hl', { to: to });
    return 'Healed ' + (to === Game.myId() ? 'you' : who(to)) + '.';
  } });
